style.css:
/* Apply to YouTube */
body {
    background: #000; /* Base black background */
    overflow: hidden; /* Hide overflow from animations */
}

/* Create the starry effect */
body::before {
    content: '';
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: radial-gradient(white, rgba(255, 255, 255, 0)) 2px 2px,
                radial-gradient(white, rgba(255, 255, 255, 0)) 4px 4px;
    background-size: 2px 2px, 4px 4px;
    opacity: 0.6;
    animation: shimmer 10s linear infinite;
    pointer-events: none; /* Ensure interactions aren't blocked */
}

/* Add twinkling stars */
body::after {
    content: '';
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: transparent;
    background-image: radial-gradient(circle, #fff 2px, transparent 2px);
    background-size: 3px 3px;
    animation: twinkle 1.5s infinite alternate ease-in-out;
    pointer-events: none; /* Ensure interactions aren't blocked */
}

/* Animation for the shimmering effect */
@keyframes shimmer {
    0% {
        opacity: 0.4;
        transform: translate3d(0, 0, 0);
    }
    50% {
        opacity: 0.6;
        transform: translate3d(0, 0.5rem, 0);
    }
    100% {
        opacity: 0.4;
        transform: translate3d(0, 0, 0);
    }
}

/* Animation for twinkling stars */
@keyframes twinkle {
    0% {
        opacity: 0.2;
    }
    100% {
        opacity: 0.8;
    }
}

/* Override YouTube's background styling */
html, body {
    background-color: black !important; /* Make the main background black */
    background-image: none !important; /* Remove YouTube's default background */
}
